BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=public,extensions;
SELECT no_plan();
INSERT INTO auth.users(id,email) VALUES('00000000-0000-4000-a098-000000000001','review-sms-owner@example.test'),('00000000-0000-4000-a098-000000000002','review-sms-other@example.test');
INSERT INTO businesses(id,owner_id,name,business_type,slug,telnyx_campaign_id,telnyx_messaging_profile_id,campaign_status)
VALUES('10000000-0000-4000-a098-000000000001','00000000-0000-4000-a098-000000000001','Review SMS','general','reviews-098','campaign-098','profile-098','approved');
INSERT INTO subscriptions(business_id,stripe_customer_id,stripe_subscription_id,plan,status,current_period_start,current_period_end)
VALUES('10000000-0000-4000-a098-000000000001','cus_098','sub_098','chat_only','active',date_trunc('month',now()),date_trunc('month',now())+interval '1 month');
INSERT INTO business_plan_family_locks(business_id,family,claimed_by) VALUES('10000000-0000-4000-a098-000000000001','chat_only','stripe_sync');
INSERT INTO phone_numbers(id,business_id,phone_number,telnyx_phone_number_id,is_active,resource_status,telnyx_campaign_assignment_status,telnyx_campaign_assignment_campaign_id)
VALUES('20000000-0000-4000-a098-000000000001','10000000-0000-4000-a098-000000000001','+15555550981','phone_098',true,'active','assigned','campaign-098');
CREATE FUNCTION pg_temp.review_access() RETURNS boolean LANGUAGE sql AS $$ SELECT has_review_sms_access('10000000-0000-4000-a098-000000000001') $$;
CREATE FUNCTION pg_temp.review_allowance() RETURNS integer LANGUAGE sql AS $$ SELECT review_sms_allowance('10000000-0000-4000-a098-000000000001') $$;
SELECT is(pg_temp.review_access(),false,'base Chat subscription never implicitly grants review texting');
SELECT ok(NOT has_table_privilege('authenticated','review_sms_accounts','UPDATE'),'owner cannot change paid/provider authority');
SELECT ok(NOT has_function_privilege('authenticated','review_sms_record_paid_period(uuid,bigint,text,text,text,timestamptz,timestamptz,integer)','EXECUTE'),'owner cannot grant paid allowance');
SELECT ok(NOT has_function_privilege('anon','has_review_sms_access(uuid)','EXECUTE'),'anonymous cannot inspect tenant SMS eligibility');
SELECT throws_ok($$SELECT review_sms_acquire_account('10000000-0000-4000-a098-000000000001','00000000-0000-4000-a098-000000000002','{}')$$,'42501','review_workspace_denied','another owner cannot configure this addon');
SELECT review_sms_acquire_account('10000000-0000-4000-a098-000000000001','00000000-0000-4000-a098-000000000001','{}');
SELECT is((SELECT billing_source FROM review_sms_accounts WHERE business_id='10000000-0000-4000-a098-000000000001'),'direct','direct Chat setup retains its base subscription binding');
UPDATE review_sms_accounts SET activation_paid_at=now(),activation_payment_intent_id='pi_098',state='carrier_pending' WHERE business_id='10000000-0000-4000-a098-000000000001';
SELECT is(pg_temp.review_access(),false,'activation payment only does not grant monthly sending');
UPDATE review_sms_accounts SET state='ready_unpaid',review_usecase_approved_at=now(),approval_evidence='Verified review marketing campaign',campaign_id='campaign-098',messaging_profile_id='profile-098',phone_number_id='20000000-0000-4000-a098-000000000001',ready_at=now(),ready_expires_at=now()+interval '7 days' WHERE business_id='10000000-0000-4000-a098-000000000001';
SELECT is(pg_temp.review_access(),false,'carrier approval alone does not grant unpaid allowance');
SELECT is(review_sms_begin_reconcile('10000000-0000-4000-a098-000000000001','sub_wrong','cus_098'),NULL::bigint,'unbound subscription cannot advance billing authority');
SELECT is(review_sms_begin_reconcile('10000000-0000-4000-a098-000000000001','sub_098','cus_098'),1::bigint,'fresh authoritative reconciliation obtains revision');
SELECT is(review_sms_record_paid_period('10000000-0000-4000-a098-000000000001',1,'si_098','price_reviews','in_partial_098',now()-interval '1 minute',date_trunc('month',now())+interval '1 month',17),true,'partial paid period grants only the quoted allowance');
SELECT is(pg_temp.review_allowance(),17,'partial period does not silently receive 250 parts');
SELECT is(pg_temp.review_access(),true,'paid bound and approved addon may send reviews');
SELECT is(tenant_sms_service_plan('10000000-0000-4000-a098-000000000001'),'chat_only','review addon never changes AI SMS service plan');
SELECT is((SELECT family FROM business_plan_family_locks WHERE business_id='10000000-0000-4000-a098-000000000001'),'chat_only','base plan family lock is preserved');
SELECT is(review_sms_record_paid_period('10000000-0000-4000-a098-000000000001',1,'si_098','price_reviews','in_partial_098',now()-interval '1 minute',date_trunc('month',now())+interval '1 month',250),false,'stale duplicate event cannot increase allowance');
UPDATE review_sms_accounts SET paid_period_end=now()-interval '1 second',paid_period_start=now()-interval '1 day' WHERE business_id='10000000-0000-4000-a098-000000000001';
SELECT is(pg_temp.review_access(),false,'expired paid window fails closed even while state is active');
UPDATE review_sms_accounts SET paid_period_end=now()+interval '1 day' WHERE business_id='10000000-0000-4000-a098-000000000001';
UPDATE businesses SET telnyx_campaign_id='other-campaign' WHERE id='10000000-0000-4000-a098-000000000001';
SELECT is(pg_temp.review_access(),false,'campaign pointer change removes prior usecase authority');
UPDATE businesses SET telnyx_campaign_id='campaign-098' WHERE id='10000000-0000-4000-a098-000000000001';
UPDATE phone_numbers SET telnyx_campaign_assignment_campaign_id='other-campaign' WHERE id='20000000-0000-4000-a098-000000000001';
SELECT is(pg_temp.review_access(),false,'bound number must belong to approved campaign');
UPDATE phone_numbers SET telnyx_campaign_assignment_campaign_id='campaign-098' WHERE id='20000000-0000-4000-a098-000000000001';
UPDATE review_sms_accounts SET state='cancel_pending',cancel_at=now()+interval '1 hour' WHERE business_id='10000000-0000-4000-a098-000000000001';
SELECT is(pg_temp.review_access(),true,'scheduled cancellation preserves already paid time');
UPDATE review_sms_accounts SET cancel_at=now()-interval '1 second' WHERE business_id='10000000-0000-4000-a098-000000000001';
SELECT is(pg_temp.review_access(),false,'period-end cancellation stops sends without waiting for a webhook');
UPDATE review_sms_accounts SET state='active',cancel_at=NULL,billing_source='grant',grant_actor='00000000-0000-4000-a098-000000000002',grant_expires_at=now()+interval '1 day' WHERE business_id='10000000-0000-4000-a098-000000000001';
SELECT is(pg_temp.review_allowance(),250,'time-bounded administrator grant has entry review allowance');
UPDATE review_sms_accounts SET grant_expires_at=now()-interval '1 second' WHERE business_id='10000000-0000-4000-a098-000000000001';
SELECT is(pg_temp.review_access(),false,'expired grant fails closed');
UPDATE review_sms_accounts SET grant_expires_at=now()+interval '1 day' WHERE business_id='10000000-0000-4000-a098-000000000001';
UPDATE businesses SET texting_paused_at=now() WHERE id='10000000-0000-4000-a098-000000000001';
SELECT is(pg_temp.review_access(),false,'owner texting pause blocks granted reviews too');
UPDATE businesses SET texting_paused_at=NULL WHERE id='10000000-0000-4000-a098-000000000001';
UPDATE subscriptions SET status='canceled' WHERE business_id='10000000-0000-4000-a098-000000000001';
SELECT is(pg_temp.review_access(),false,'grant cannot override a canceled authoritative base subscription');
UPDATE subscriptions SET status='active',plan='full' WHERE business_id='10000000-0000-4000-a098-000000000001';
UPDATE review_sms_accounts SET billing_source='included' WHERE business_id='10000000-0000-4000-a098-000000000001';
SELECT is(pg_temp.review_allowance(),0,'higher plans share their existing pool without an extra 250');
SELECT is(pg_temp.review_access(),true,'approved review usecase enables higher-plan shared-pool sends');
UPDATE review_sms_accounts SET review_usecase_approved_at=NULL WHERE business_id='10000000-0000-4000-a098-000000000001';
SELECT is(pg_temp.review_access(),false,'ordinary campaign approval does not grant review-usecase permission');
UPDATE subscriptions SET plan='chat_only' WHERE business_id='10000000-0000-4000-a098-000000000001';
UPDATE review_sms_accounts SET billing_source='direct',state='ready_unpaid',review_usecase_approved_at=now(),ready_expires_at=now()+interval '1 hour',stripe_item_id=NULL,provider_started_at=NULL,cancel_at=NULL WHERE business_id='10000000-0000-4000-a098-000000000001';
CREATE TEMP TABLE operation_ids(kind text,id uuid);
INSERT INTO operation_ids SELECT 'refund',(review_sms_acquire_operation('10000000-0000-4000-a098-000000000001','00000000-0000-4000-a098-000000000001','refund','refund-fingerprint','{}')).id;
INSERT INTO operation_ids SELECT 'recurring',(review_sms_acquire_operation('10000000-0000-4000-a098-000000000001','00000000-0000-4000-a098-000000000001','recurring','recurring-fingerprint','{}')).id;
SELECT lives_ok($$SELECT review_sms_confirm_operation((SELECT id FROM operation_ids WHERE kind='recurring'),'00000000-0000-4000-a098-000000000001','recurring-fingerprint')$$,'prepared recurring operation can confirm');
SELECT throws_ok($$SELECT review_sms_confirm_operation((SELECT id FROM operation_ids WHERE kind='refund'),'00000000-0000-4000-a098-000000000001','refund-fingerprint')$$,'P0001','review_sms_operation_in_progress','a confirmed payment blocks a concurrent refund');
SELECT throws_ok($$SELECT review_sms_acquire_operation('10000000-0000-4000-a098-000000000001','00000000-0000-4000-a098-000000000001','cancel','cancel-fingerprint','{}')$$,'P0001','review_sms_operation_in_progress','another confirmed operation blocks acquiring a conflicting action');
UPDATE review_sms_accounts SET ready_expires_at=now()-interval '1 second' WHERE business_id='10000000-0000-4000-a098-000000000001';
SELECT lives_ok($$SELECT review_sms_confirm_operation((SELECT id FROM operation_ids WHERE kind='recurring'),'00000000-0000-4000-a098-000000000001','recurring-fingerprint')$$,'confirmed recurring retry keeps its frozen provider request when setup deadline passes');
UPDATE review_sms_billing_operations SET state='completed' WHERE id=(SELECT id FROM operation_ids WHERE kind='recurring');
UPDATE review_sms_accounts SET provider_started_at=now() WHERE business_id='10000000-0000-4000-a098-000000000001';
SELECT throws_ok($$SELECT review_sms_confirm_operation((SELECT id FROM operation_ids WHERE kind='refund'),'00000000-0000-4000-a098-000000000001','refund-fingerprint')$$,'P0001','review_sms_refund_unavailable','paid provider boundary invalidates an older prepared refund');
UPDATE review_sms_accounts SET state='active' WHERE business_id='10000000-0000-4000-a098-000000000001';
INSERT INTO operation_ids SELECT 'cancel',(review_sms_acquire_operation('10000000-0000-4000-a098-000000000001','00000000-0000-4000-a098-000000000001','cancel','cancel-fingerprint','{}')).id;
SELECT review_sms_confirm_operation((SELECT id FROM operation_ids WHERE kind='cancel'),'00000000-0000-4000-a098-000000000001','cancel-fingerprint');
SELECT lives_ok($$SELECT review_sms_freeze_cancel((SELECT id FROM operation_ids WHERE kind='cancel'),'00000000-0000-4000-a098-000000000001','schedule-098','{"end_behavior":"release","phases":[{"start_date":1,"end_date":2,"items":[]}]}')$$,'cancellation persists exact provider parameters before its first update');
SELECT is((review_sms_freeze_cancel((SELECT id FROM operation_ids WHERE kind='cancel'),'00000000-0000-4000-a098-000000000001','schedule-098','{"end_behavior":"cancel"}')).payload->'scheduleUpdate'->>'end_behavior','release','cancellation retry cannot change frozen provider parameters');
SELECT throws_ok($$SELECT review_sms_freeze_cancel((SELECT id FROM operation_ids WHERE kind='cancel'),'00000000-0000-4000-a098-000000000001','other-schedule','{}')$$,'P0001','review_sms_cancel_recovery_required','cancellation retry cannot target another schedule');
SELECT throws_ok($$SELECT review_sms_freeze_cancel((SELECT id FROM operation_ids WHERE kind='cancel'),'00000000-0000-4000-a098-000000000001','schedule-098',NULL)$$,'P0001','review_sms_cancel_recovery_required','null cancellation parameters fail closed');
SELECT ok(NOT has_function_privilege('authenticated','review_sms_freeze_cancel(uuid,uuid,text,jsonb)','EXECUTE'),'owner cannot forge frozen provider schedule authority');
UPDATE review_sms_accounts SET state='carrier_pending',billing_source='included',provider_started_at=NULL,provisioning_claim=NULL,provisioning_lease_until=NULL WHERE business_id='10000000-0000-4000-a098-000000000001';
SELECT isnt(review_sms_claim_provisioning('10000000-0000-4000-a098-000000000001'),NULL::uuid,'first provisioning claim accepts a null prior lease');
SELECT is((SELECT provider_started_at FROM review_sms_accounts WHERE business_id='10000000-0000-4000-a098-000000000001'),NULL::timestamptz,'claim alone does not consume refundable paid-provider boundary');
SELECT is(review_sms_claim_provisioning('10000000-0000-4000-a098-000000000001'),NULL::uuid,'active provisioning lease rejects a second worker');
UPDATE businesses SET owner_id=NULL WHERE id='10000000-0000-4000-a098-000000000001';
SELECT is((SELECT count(*)::integer FROM review_sms_accounts WHERE business_id='10000000-0000-4000-a098-000000000001'),0,'owner cleanup removes addon account and draft PII');
SELECT * FROM finish();
ROLLBACK;
